package com.contextgraph.model; import jakarta.persistence.*; @Entity @Table(name="graph_relations") public class GraphRelation {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long sourceNodeId; Long targetNodeId; @Column(nullable=false) String relationType; Double strength; public Long getId(){return id;} public Long getSourceNodeId(){return sourceNodeId;} public Long getTargetNodeId(){return targetNodeId;} public String getRelationType(){return relationType;} public Double getStrength(){return strength;} public void setSourceNodeId(Long v){sourceNodeId=v;} public void setTargetNodeId(Long v){targetNodeId=v;} public void setRelationType(String v){relationType=v;} public void setStrength(Double v){strength=v;}}